"""Pinned read-only origin collector queries. No credential or connector code."""

MANIFEST = b"\nWITH roles AS (SELECT rolname AS name,rolsuper AS superuser,rolinherit AS inherit,\n rolcreaterole AS create_role,rolcreatedb AS create_db,rolreplication AS replication,\n rolbypassrls AS bypass_rls,rolcanlogin AS can_login FROM pg_roles), members AS (\n SELECT r.rolname AS role,m.rolname AS member,g.rolname AS grantor,\n a.admin_option AS admin,a.inherit_option AS inherit,a.set_option AS set_role\n FROM pg_auth_members a JOIN pg_roles r ON r.oid=a.roleid JOIN pg_roles m ON m.oid=a.member\n JOIN pg_roles g ON g.oid=a.grantor)\nSELECT json_build_object('roles',(SELECT json_agg(row_to_json(r) ORDER BY name) FROM roles r),\n 'memberships',(SELECT coalesce(json_agg(row_to_json(m) ORDER BY role,member,grantor),'[]') FROM members m),\n 'extensions',(SELECT json_agg(json_build_object('name',e.extname,'version',e.extversion,\n 'schema',n.nspname,'owner',r.rolname) ORDER BY e.extname) FROM pg_extension e\n JOIN pg_namespace n ON n.oid=e.extnamespace JOIN pg_roles r ON r.oid=e.extowner),\n 'events',(SELECT coalesce(json_agg(json_build_object('name',e.evtname,'owner',r.rolname,\n 'enabled',e.evtenabled) ORDER BY e.evtname),'[]') FROM pg_event_trigger e JOIN pg_roles r ON r.oid=e.evtowner),\n 'schemas',(SELECT json_agg(json_build_object('name',n.nspname,'owner',r.rolname,'acl',n.nspacl::text) ORDER BY n.nspname)\n FROM pg_namespace n JOIN pg_roles r ON r.oid=n.nspowner WHERE n.nspname!~'^pg_' AND n.nspname<>'information_schema'),\n 'default_acl',(SELECT coalesce(json_agg(json_build_object('owner',r.rolname,'schema',n.nspname,'kind',d.defaclobjtype,'acl',d.defaclacl::text) ORDER BY r.rolname,n.nspname,d.defaclobjtype),'[]')\n FROM pg_default_acl d JOIN pg_roles r ON r.oid=d.defaclrole LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace),\n 'functions',(SELECT json_agg(json_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'owner',r.rolname,'security_definer',p.prosecdef,'acl',p.proacl::text)\n ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_roles r ON r.oid=p.proowner WHERE n.nspname!~'^pg_' AND n.nspname<>'information_schema'),\n 'catalog',(SELECT json_agg(json_build_object('name',c.relname,'owner',r.rolname,\n 'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'acl',c.relacl::text) ORDER BY c.relname)\n FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_roles r ON r.oid=c.relowner\n WHERE n.nspname='public' AND c.relkind IN('r','p')))\n"

Q_IDENTITY = 'SELECT s.system_identifier::text, d.oid::bigint, d.datname FROM pg_control_system() s, pg_database d WHERE d.datname=current_database()'

Q_LEDGER = 'SELECT name FROM public.schema_migrations ORDER BY name COLLATE "C"'

Q_CATALOG = 'SELECT kind, name, md5(definition) AS hash FROM (SELECT \'namespace\'::text AS kind, n.nspname::text AS name, row(n.nspowner::regrole, coalesce(n.nspacl, acldefault(\'n\', n.nspowner)))::text AS definition FROM pg_namespace n WHERE n.nspname=\'public\' UNION ALL SELECT \'default-acl\', d.defaclrole::regrole::text || \':\' || d.defaclobjtype::text || \':\' || CASE WHEN d.defaclnamespace=0 THEN \'*\' ELSE \'public\' END, row(d.defaclacl)::text FROM pg_default_acl d WHERE d.defaclnamespace IN (0, (SELECT oid FROM pg_namespace WHERE nspname=\'public\')) UNION ALL SELECT \'extension\', e.extname::text, row(e.extversion, e.extowner::regrole, e.extrelocatable)::text FROM pg_extension e WHERE e.extnamespace=(SELECT oid FROM pg_namespace WHERE nspname=\'public\') UNION ALL SELECT \'relation\', c.relname::text, row(c.relkind, c.relowner::regrole, coalesce(c.relacl, acldefault(CASE WHEN c.relkind=\'S\' THEN \'s\'::"char" ELSE \'r\'::"char" END, c.relowner)), c.relrowsecurity, c.relforcerowsecurity, c.relpersistence, c.relreplident, c.reloptions, c.relispartition, c.reloftype::regtype, CASE WHEN c.relkind IN (\'v\', \'m\') THEN pg_get_viewdef(c.oid) END, pg_get_partkeydef(c.oid), pg_get_expr(c.relpartbound, c.oid), ARRAY(SELECT h.inhparent::regclass::text FROM pg_inherits h WHERE h.inhrelid=c.oid ORDER BY h.inhseqno))::text FROM pg_class c WHERE c.relnamespace=(SELECT oid FROM pg_namespace WHERE nspname=\'public\') UNION ALL SELECT \'attribute\', c.relname || \'.\' || a.attname, row(a.attnum, format_type(a.atttypid, a.atttypmod), a.attnotnull, a.atthasdef, pg_get_expr(d.adbin, d.adrelid), a.attidentity, a.attgenerated, a.attcollation::regcollation, a.attacl, a.attoptions, a.attstorage)::text FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE c.relnamespace=(SELECT oid FROM pg_namespace WHERE nspname=\'public\') AND a.attnum>0 AND NOT a.attisdropped UNION ALL SELECT \'constraint\', coalesce(c.relname::text, k.contypid::regtype::text) || \'.\' || k.conname, row(k.contype, k.condeferrable, k.condeferred, k.convalidated, k.connoinherit, pg_get_constraintdef(k.oid))::text FROM pg_constraint k LEFT JOIN pg_class c ON c.oid=k.conrelid WHERE k.connamespace=(SELECT oid FROM pg_namespace WHERE nspname=\'public\') UNION ALL SELECT \'index\', c.relname::text, row(pg_get_indexdef(i.indexrelid), i.indisunique, i.indisprimary, i.indisexclusion, i.indimmediate, i.indisvalid, i.indisready, i.indislive, i.indisreplident, i.indnullsnotdistinct)::text FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE c.relnamespace=(SELECT oid FROM pg_namespace WHERE nspname=\'public\') UNION ALL SELECT \'trigger\', c.relname || \'.\' || t.tgname, row(t.tgenabled, pg_get_triggerdef(t.oid))::text FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relnamespace=(SELECT oid FROM pg_namespace WHERE nspname=\'public\') AND NOT t.tgisinternal UNION ALL SELECT \'rule\', c.relname || \'.\' || r.rulename, row(r.ev_enabled, pg_get_ruledef(r.oid))::text FROM pg_rewrite r JOIN pg_class c ON c.oid=r.ev_class WHERE c.relnamespace=(SELECT oid FROM pg_namespace WHERE nspname=\'public\') UNION ALL SELECT \'policy\', c.relname || \'.\' || p.polname, row(p.polcmd, p.polpermissive, ARRAY(SELECT r::regrole::text FROM unnest(p.polroles) r ORDER BY 1), pg_get_expr(p.polqual, p.polrelid), pg_get_expr(p.polwithcheck, p.polrelid))::text FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid WHERE c.relnamespace=(SELECT oid FROM pg_namespace WHERE nspname=\'public\') UNION ALL SELECT \'function\', p.oid::regprocedure::text, row(p.prokind, p.proowner::regrole, coalesce(p.proacl, acldefault(\'f\', p.proowner)), p.proconfig, p.prosecdef, p.proleakproof, p.proisstrict, p.provolatile, p.proparallel, pg_get_function_result(p.oid), CASE WHEN p.prokind <> \'a\' THEN pg_get_functiondef(p.oid) END, (SELECT row(g.aggkind, g.aggtransfn::regproc, g.aggfinalfn::regproc, g.aggcombinefn::regproc, g.aggtranstype::regtype, g.agginitval)::text FROM pg_aggregate g WHERE g.aggfnoid=p.oid))::text FROM pg_proc p WHERE p.pronamespace=(SELECT oid FROM pg_namespace WHERE nspname=\'public\') UNION ALL SELECT \'type\', t.oid::regtype::text, row(t.typtype, t.typowner::regrole, coalesce(t.typacl, acldefault(\'T\', t.typowner)), t.typnotnull, t.typdefault, format_type(t.typbasetype, t.typtypmod), t.typcollation::regcollation, ARRAY(SELECT e.enumlabel::text FROM pg_enum e WHERE e.enumtypid=t.oid ORDER BY e.enumsortorder))::text FROM pg_type t WHERE t.typnamespace=(SELECT oid FROM pg_namespace WHERE nspname=\'public\') UNION ALL SELECT \'sequence\', c.relname::text, row(s.seqtypid::regtype, s.seqstart, s.seqincrement, s.seqmax, s.seqmin, s.seqcache, s.seqcycle)::text FROM pg_sequence s JOIN pg_class c ON c.oid=s.seqrelid WHERE c.relnamespace=(SELECT oid FROM pg_namespace WHERE nspname=\'public\')) catalog ORDER BY kind COLLATE "C", name COLLATE "C", 3'

TABLES = b"SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(n.nspname,c.relname) ORDER BY n.nspname,c.relname),'[]') FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN('r','p','m') AND n.nspname!~'^pg_' AND n.nspname<>'information_schema';"

SETTINGS = b"\nSELECT coalesce(jsonb_agg(jsonb_build_object(\n 'scope',CASE WHEN s.setdatabase=0 AND s.setrole=0 THEN 'all'\n              WHEN s.setdatabase=0 THEN 'role'\n              WHEN s.setrole=0 THEN 'database' ELSE 'role-database' END,\n 'role',r.rolname,'key',split_part(v,'=',1),\n 'value',CASE WHEN split_part(v,'=',1) IN\n ('search_path','statement_timeout','lock_timeout','idle_in_transaction_session_timeout',\n  'default_transaction_read_only','app.settings.jwt_exp','log_statement','session_preload_libraries')\n THEN substring(v FROM position('=' IN v)+1) ELSE NULL END)\n ORDER BY s.setdatabase,s.setrole,split_part(v,'=',1)),'[]')\nFROM pg_catalog.pg_db_role_setting s LEFT JOIN pg_catalog.pg_roles r ON r.oid=s.setrole\nCROSS JOIN LATERAL unnest(s.setconfig) v\nWHERE s.setdatabase=0 OR s.setdatabase=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database());\n"

BEGIN = b"BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY; SET LOCAL statement_timeout='8s'; SET LOCAL lock_timeout='1s'; SET LOCAL search_path=pg_catalog;"
ROLLBACK = b'ROLLBACK;'
PING = b'SELECT pg_catalog.to_json(1);'
TLS = b"SELECT jsonb_build_object('ssl',ssl,'protocol',version,'cipher',cipher,'bits',bits) FROM pg_catalog.pg_stat_ssl WHERE pid=pg_catalog.pg_backend_pid();"
SAFETY = b"SELECT jsonb_build_object('database',current_database(),'role',current_user,'session_role',session_user,'version',current_setting('server_version_num'),'readonly',current_setting('transaction_read_only'),'isolation',current_setting('transaction_isolation'));"
IDENTITY = ('SELECT jsonb_build_array(x.system_identifier,x.oid,x.datname) FROM ('+Q_IDENTITY+') x;').encode()
LEDGER = ('SELECT coalesce(jsonb_agg(x.name ORDER BY x.name COLLATE "C"),\'[]\') FROM ('+Q_LEDGER+') x;').encode()
CATALOG = ('SELECT coalesce(jsonb_agg(jsonb_build_array(x.kind,x.name,x.hash) ORDER BY x.kind COLLATE "C",x.name COLLATE "C",x.hash),\'[]\') FROM ('+Q_CATALOG+') x;').encode()

def count_table(namespace,table):
    def quote(v):
        if type(v)is not str or not 0<len(v)<=1024 or '\x00' in v:raise ValueError('origin-count-identifier')
        return '"'+v.replace('"','""')+'"'
    return ('SELECT to_json(count(*)) FROM '+quote(namespace)+'.'+quote(table)+';').encode()

def holder_absent(pid):
    if type(pid)is not int or pid<=0:raise ValueError('origin-holder-pid')
    return ('SELECT to_json(count(*)) FROM pg_catalog.pg_stat_activity WHERE pid='+str(pid)+';').encode()

V1_PATH=b'SET LOCAL search_path=pg_catalog,public;'
V3_PATH=b'SET LOCAL search_path=pg_catalog;'
